<?php
declare(strict_types=1);

require_once 'db.php';
require_once dirname(__DIR__) . '/core/InputRevision.php';
$db=Database::getInstance(); api_require_permission('logistics.read');
$id=trim((string)($_GET['spb_id']??'')); if($id==='')api_json_response(422,['status'=>'error','message'=>'spb_id wajib diisi.']);
$stmt=$db->prepare('SELECT pr.*,a.asset_code,u.full_name requester_name FROM purchase_requests pr LEFT JOIN assets a ON a.asset_id=pr.asset_id LEFT JOIN users u ON u.user_id=pr.requested_by WHERE pr.spb_id=:id LIMIT 1');$stmt->execute([':id'=>$id]);$spb=$stmt->fetch(PDO::FETCH_ASSOC);
if(!$spb)api_json_response(404,['status'=>'error','message'=>'SPB tidak ditemukan.']); if(!empty($spb['asset_id']))api_require_asset_access($db,(string)$spb['asset_id']);
$items=$db->prepare('SELECT part_number,description,qty_requested,transaction_uom,base_quantity,status FROM purchase_request_items WHERE spb_id=:id ORDER BY id');$items->execute([':id'=>$id]);$history=InputRevision::history($db,'SPB',$id);
$official=in_array((string)$spb['status'],['Approved','Ordered','Issued','Closed'],true);
header('Content-Type: text/html; charset=UTF-8');
$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
?><!doctype html><html lang="id"><head><meta charset="utf-8"><title><?= $e($id) ?></title><style>body{font-family:Arial,sans-serif;color:#172033;margin:32px}.sheet{max-width:900px;margin:auto;position:relative}.watermark{position:fixed;inset:40% 0;text-align:center;font-size:72px;font-weight:800;color:rgba(180,30,30,.12);transform:rotate(-22deg);pointer-events:none}header{display:flex;justify-content:space-between;border-bottom:3px solid #172033;padding-bottom:16px}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{border:1px solid #9aa4b2;padding:8px;text-align:left}.badge{border:1px solid #172033;padding:4px 8px;font-weight:700}.history{margin-top:24px;font-size:12px}@media print{button{display:none}body{margin:12mm}}</style></head><body><?php if(!$official):?><div class="watermark">DRAFT · TIDAK RESMI</div><?php endif;?><main class="sheet"><header><div><h1>Surat Permintaan Barang</h1><strong><?= $e($id) ?><?= (int)$spb['revision_no']>0?' · Rev. '.(int)$spb['revision_no']:'' ?></strong></div><span class="badge"><?= $e($spb['status']) ?></span></header><p>Unit: <strong><?= $e($spb['asset_code']?:$spb['asset_id']) ?></strong> · WO: <?= $e($spb['wo_id']) ?> · Pemohon: <?= $e($spb['requester_name']) ?></p><table><thead><tr><th>SKU</th><th>Deskripsi</th><th>Qty</th><th>Base Qty</th><th>Status</th></tr></thead><tbody><?php foreach($items->fetchAll(PDO::FETCH_ASSOC) as $item):?><tr><td><?= $e($item['part_number']) ?></td><td><?= $e($item['description']) ?></td><td><?= $e($item['qty_requested'].' '.($item['transaction_uom']?:'')) ?></td><td><?= $e($item['base_quantity']) ?></td><td><?= $e($item['status']) ?></td></tr><?php endforeach;?></tbody></table><section class="history"><h2>Riwayat status/revisi</h2><?php if(!$history):?><p>Belum ada riwayat revisi.</p><?php else:foreach($history as $event):?><p><strong><?= $e($event['action']) ?></strong> · <?= $e($event['created_at']) ?> · <?= $e($event['reason']) ?></p><?php endforeach;endif;?></section><button onclick="window.print()">Cetak</button></main></body></html>
